INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt", "verifiedAt", "authorName")
VALUES
(gen_random_uuid(), 'nz-police-intelligence-analyst-jobs-20261122', 'global', 'New Zealand',
'NZ Police Intelligence Analyst Jobs: Interpol Role in Wellington',
'NZ प्रहरी गुप्तचर विश्लेषक जागिर: वेलिङ्टनमा इन्टरपोल',
'NZ Police intelligence analyst jobs: Interpol role in Wellington pays $87,306 to $91,953. Applications close 25 November 2026.',
'NZ प्रहरी गुप्तचर विश्लेषक जागिर: वेलिङ्टनमा इन्टरपोल भूमिकाको तलब $87,306 देखि $91,953। आवेदन २५ नोभेम्बर २०२६ मा बन्द हुन्छ।',
$$<p>New Zealand Police is hiring for NZ Police intelligence analyst jobs, with an Intelligence Analyst post in International Operations at Police National Headquarters in Wellington, supporting INTERPOL Wellington and EUROPOL. Applications close at 5:00pm on Tuesday 25 November 2026.</p><table><tbody><tr><td>Organisation</td><td>New Zealand Police, Police National Headquarters, Wellington</td></tr><tr><td>Post</td><td>Intelligence Analyst, International Operations (INTERPOL), requisition JR 6103368, permanent full time</td></tr><tr><td>Pay</td><td>$87,306 to $91,953 depending on skills and experience, under a collective agreement</td></tr><tr><td>Application dates</td><td>Posted 11 November 2026; deadline 5:00pm, Tuesday 25 November 2026</td></tr><tr><td>Application route</td><td>Online through NZ Government Jobs</td></tr><tr><td>Qualification</td><td>As set out in the position description on the NZ Police careers site</td></tr></tbody></table><h2>What the NZ Police intelligence analyst job involves</h2><p>As Intelligence Analyst for International Operations, you will contribute to the intelligence requirements of INTERPOL Wellington, the National Central Bureau, and EUROPOL, the National Contact Point, preparing nationally standardised strategic, operational and tactical intelligence products that inform prevention, intervention and enforcement work. The role is at Individual Contributor and Emerging Leader level, and it is based at Police National Headquarters in Wellington. New Zealand Police has more than 13,000 staff and provides policing 24 hours a day, so the international operations work sits inside a large national organisation. Readers following other <a href="https://growentix.cloud/global">global jobs</a> can also read our report on <a href="https://growentix.cloud/articles/fbi-intelligence-analyst-special-agent-jobs-20261121">FBI intelligence analyst and special agent jobs</a>, another intelligence hiring round closing soon.</p><h2>Who can apply</h2><p>Applicants should read the position description on the New Zealand Police careers site in full, since the vacancy summary I read does not spell out the essential qualifications or experience. The post is listed as Office of Constable or Police Employee, permanent and full time. The listing notes that applications may be reviewed before the close date and candidates may be contacted early, so applying promptly matters more than usual.</p><h2>What it pays</h2><p>Pay is covered by a collective agreement and will commence between $87,306 and $91,953, depending on skills and experience relevant to the role. The listing gives that range as the starting point rather than the full band, so the top of the range is not stated.</p><h2>How to apply</h2><p>Apply online through NZ Government Jobs, searching for the New Zealand Police Intelligence Analyst, International Operations vacancy, requisition JR 6103368, before 5:00pm on Tuesday 25 November 2026. Read the position description on police.govt.nz first, since it carries the detailed requirements the summary does not.</p><h2>What the notice does not say</h2><p>The vacancy summary does not state how many Intelligence Analyst posts are open, and it does not spell out the essential qualifications, experience or security requirements in the text I read. It does not state whether applicants from outside New Zealand can apply, and it does not give an interview date or a start date.</p><p><strong>Never pay anyone to apply for this job.</strong> NZ Government Jobs applications are free, and New Zealand Police will never ask for money in exchange for an application, an assessment or a job offer.</p><p>Sources: <a href="https://jobs.govt.nz/jobtools/jncustomsearch.viewFullSingle?in_organid=16563&amp;in_jnCounter=226726360">NZ Government Jobs</a>, the official vacancy listing (pay, requisition number, deadline and role description); <a href="https://www.police.govt.nz/careers">New Zealand Police</a>, the official careers site carrying the position description.</p><h2>Frequently asked questions</h2><h3>What is the pay?</h3><p>$87,306 to $91,953, depending on skills and experience, under a collective agreement.</p><h3>When do applications close?</h3><p>Applications close at 5:00pm on Tuesday 25 November 2026, and applications may be reviewed before the close date.</p><h3>What is INTERPOL Wellington?</h3><p>INTERPOL Wellington is the National Central Bureau, and the role also supports EUROPOL as the National Contact Point.</p><h3>Where is the role based?</h3><p>Police National Headquarters in Wellington.</p>$$,
$$<p>न्युजिल्यान्ड प्रहरीले NZ प्रहरी गुप्तचर विश्लेषक जागिरका लागि वेलिङ्टनमा प्रहरी राष्ट्रिय मुख्यालयमा अन्तर्राष्ट्रिय सञ्चालनमा गुप्तचर विश्लेषक पदका लागि आवेदन खुलाएको छ, जसले इन्टरपोल वेलिङ्टन र युरोपोललाई सहयोग गर्छ। आवेदन मंगलबार २५ नोभेम्बर २०२६ साँझ ५:०० बजे बन्द हुन्छ।</p><table><tbody><tr><td>संस्था</td><td>न्युजिल्यान्ड प्रहरी, प्रहरी राष्ट्रिय मुख्यालय, वेलिङ्टन</td></tr><tr><td>पद</td><td>गुप्तचर विश्लेषक, अन्तर्राष्ट्रिय सञ्चालन (इन्टरपोल), माग JR ६१०३३६८, स्थायी पूर्णकालीन</td></tr><tr><td>तलब</td><td>सीप र अनुभवअनुसार $87,306 देखि $91,953, सामूहिक सम्झौताअन्तर्गत</td></tr><tr><td>आवेदन मिति</td><td>११ नोभेम्बर २०२६ मा प्रकाशित; अन्तिम मिति मंगलबार २५ नोभेम्बर २०२६ साँझ ५:०० बजे</td></tr><tr><td>आवेदन तरिका</td><td>NZ सरकारी जागिरबाट अनलाइन</td></tr><tr><td>योग्यता</td><td>NZ प्रहरी करियर साइटमा पद विवरणमा उल्लेख भएअनुसार</td></tr></tbody></table><h2>पद के हो</h2><p>अन्तर्राष्ट्रिय सञ्चालनका लागि गुप्तचर विश्लेषकका रूपमा तपाईंले इन्टरपोल वेलिङ्टन, राष्ट्रिय केन्द्रीय ब्युरो, र युरोपोल, राष्ट्रिय सम्पर्क बिन्दुको गुप्तचर आवश्यकतामा योगदान गर्नुहुनेछ, रोकथाम, हस्तक्षेप र प्रवर्तन कार्यलाई जानकारी दिने राष्ट्रिय रूपमा मानकीकृत रणनीतिक, परिचालन र युक्तिगत गुप्तचर उत्पादनहरू तयार गरेर। भूमिका व्यक्तिगत योगदानकर्ता र उदीयमान नेता तहमा छ, र वेलिङ्टनमा प्रहरी राष्ट्रिय मुख्यालयमा आधारित छ।</p><h2>कसले आवेदन दिन सक्छ</h2><p>आवेदकले न्युजिल्यान्ड प्रहरी करियर साइटमा पद विवरण पूरा पढ्नुपर्छ, किनकि मैले पढेको रिक्ति सारांशले आवश्यक योग्यता वा अनुभव बताएको छैन। पद कन्स्टेबल कार्यालय वा प्रहरी कर्मचारीका रूपमा सूचीबद्ध छ, स्थायी र पूर्णकालीन। सूचीले आवेदन अन्तिम मितिअघि समीक्षा गर्न सकिन्छ र उम्मेदवारलाई चाँडै सम्पर्क गर्न सकिन्छ भन्ने उल्लेख गर्छ।</p><h2>तलब कति छ</h2><p>तलब सामूहिक सम्झौताले समेट्छ र भूमिकासँग सम्बन्धित सीप र अनुभवअनुसार $87,306 देखि $91,953 बाट सुरु हुनेछ। सूचीले त्यो दायरालाई सुरुवाती बिन्दुका रूपमा दिन्छ, पूर्ण ब्यान्डको माथिल्लो सीमा बताएको छैन।</p><h2>कसरी आवेदन दिने</h2><p>NZ सरकारी जागिरबाट अनलाइन आवेदन दिनुहोस्, न्युजिल्यान्ड प्रहरी गुप्तचर विश्लेषक, अन्तर्राष्ट्रिय सञ्चालन रिक्ति खोजेर, माग JR ६१०३३६८, मंगलबार २५ नोभेम्बर २०२६ साँझ ५:०० बजेअघि। पहिले police.govt.nz मा पद विवरण पढ्नुहोस्, किनकि त्यसमा सारांशले नदिएको विस्तृत आवश्यकता छ।</p><h2>सूचनाले के भनेको छैन</h2><p>रिक्ति सारांशले कति गुप्तचर विश्लेषक पद खुलेका छन् भन्ने बताएको छैन, र मैले पढेको पाठमा आवश्यक योग्यता, अनुभव वा सुरक्षा आवश्यकताहरू पनि बताएको छैन। न्युजिल्यान्ड बाहिरका आवेदकले आवेदन दिन सक्छन् कि सक्दैनन् भन्ने पनि बताएको छैन, र अन्तर्वार्ता मिति वा सुरु मिति पनि दिएको छैन।</p><p><strong>यो जागिरका लागि कसैलाई पनि पैसा नतिर्नुहोस्।</strong> NZ सरकारी जागिरमा आवेदन निःशुल्क छ, र न्युजिल्यान्ड प्रहरीले आवेदन, मूल्याङ्कन वा जागिर प्रस्तावका लागि कहिल्यै पैसा माग्दैन।</p><p>स्रोतहरू: <a href="https://jobs.govt.nz/jobtools/jncustomsearch.viewFullSingle?in_organid=16563&amp;in_jnCounter=226726360">NZ सरकारी जागिर</a>, आधिकारिक रिक्ति सूची; <a href="https://www.police.govt.nz/careers">न्युजिल्यान्ड प्रहरी</a>, पद विवरणसहित आधिकारिक करियर साइट।</p><h2>बारम्बार सोधिने प्रश्नहरू</h2><h3>तलब कति छ?</h3><p>सीप र अनुभवअनुसार $87,306 देखि $91,953, सामूहिक सम्झौताअन्तर्गत।</p><h3>आवेदन कहिले बन्द हुन्छ?</h3><p>आवेदन मंगलबार २५ नोभेम्बर २०२६ साँझ ५:०० बजे बन्द हुन्छ, र आवेदन अन्तिम मितिअघि समीक्षा गर्न सकिन्छ।</p><h3>इन्टरपोल वेलिङ्टन भनेको के हो?</h3><p>इन्टरपोल वेलिङ्टन राष्ट्रिय केन्द्रीय ब्युरो हो, र भूमिकाले युरोपोललाई राष्ट्रिय सम्पर्क बिन्दुका रूपमा पनि सहयोग गर्छ।</p>$$,
ARRAY['https://jobs.govt.nz/jobtools/jncustomsearch.viewFullSingle?in_organid=16563&in_jnCounter=226726360', 'https://www.police.govt.nz/careers'], NOW(), NOW(), NOW(), '2026-11-20'::timestamptz, NULL) ON CONFLICT ("slug") DO NOTHING;

-- va-nursing-assistant-jobs-miami-20261122 (usa; English 742 words; Nepali 479 words; verifiedAt '2026-11-20'::timestamptz)
INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt", "verifiedAt", "authorName")
VALUES
(gen_random_uuid(), 'va-nursing-assistant-jobs-miami-20261122', 'usa', 'USA',
'VA Nursing Assistant Jobs in Miami: GS-5, Close 4 December',
'VA नर्सिङ सहायक जागिर: मियामीमा GS-5',
'VA nursing assistant jobs in Miami are open at GS-5 across several shifts in the Miami VA Healthcare System. Apply by 4 December 2026.',
'VA नर्सिङ सहायक जागिर: मियामी VA स्वास्थ्य सेवा प्रणालीमा GS-5 मा धेरै सिफ्टमा खुलेका छन्। आवेदन ४ डिसेम्बर २०२६ मा बन्द हुन्छ।',
$$<p>The Bruce W. Carter Department of Veterans Affairs Medical Center in Miami is hiring for VA nursing assistant jobs, with Nursing Assistant posts open across its service lines and departments. Applications close on Friday 4 December 2026, after the closing date was amended from 4 November 2026.</p><table><tbody><tr><td>Organisation</td><td>Bruce W. Carter Department of Veterans Affairs Medical Center, Miami VA Healthcare System</td></tr><tr><td>Post</td><td>Nursing Assistant, full performance level GS-5, various shifts</td></tr><tr><td>Pay</td><td>GS-5 grade; the announcement does not state a dollar salary figure</td></tr><tr><td>Application dates</td><td>Closing Friday 4 December 2026, amended from 4 November 2026; selections over the next 90 days</td></tr><tr><td>Application route</td><td>Online through USAJobs</td></tr><tr><td>Qualification</td><td>Six months of general experience, or one year of education above high school with NA-related courses</td></tr><tr><td>Selection</td><td>Application review against the VA qualification standard, then interview</td></tr></tbody></table><h2>What the VA nursing assistant job involves</h2><p>Nursing Assistants at the Miami VA work as members of the nursing care team, supporting licensed nursing staff by identifying and reporting safety concerns and providing direct care for veterans with acute to chronic conditions. The work covers outpatient, inpatient, home and community living care, and acute and sub-acute settings. Duties include glucose monitoring, catheterisation, colostomy care, skin care and simple dressings, applying braces and prosthetic devices, and acting as the unit safe patient handling liaison. Shifts vary and may include daytime, afternoon and evening hours, weekends, nights and some holidays. Readers following other <a href="https://growentix.cloud/usa">USA jobs</a> can also read our report on <a href="https://growentix.cloud/articles/va-veterans-service-representative-jobs-20261105">VA Veterans Service Representative jobs</a>, another Department of Veterans Affairs hiring round.</p><h2>Who can apply</h2><p>Applicants must be US citizens; the announcement notes non-citizens may only be appointed when it is not possible to recruit qualified citizens, under VA policy. The basic requirement is six months of general experience showing the ability to acquire the knowledge and skills of a Nursing Assistant, or one year of education above high school with courses related to the occupation. For the GS-5 full performance level, applicants need one year of progressively responsible experience at GS-4 level, or a four year course of study above high school leading to a bachelors degree with 24 semester hours in health care courses, plus demonstrated knowledge, skills and abilities. Applicants must be proficient in written and spoken English, pass a pre-employment physical evaluation, a background and security investigation and a drug test, and take part in the seasonal influenza vaccination programme. A one or two year trial period applies.</p><h2>What it pays</h2><p>Pay is set at the GS-5 grade, the full performance level for this vacancy. The announcement text I read does not state a dollar salary figure, so the exact pay depends on the GS-5 step offered and the Miami locality rate. The announcement does not state allowances either, so applicants should check the pay line on the USAJobs posting before applying.</p><h2>How to apply</h2><p>Apply online through USAJobs, on the Miami VA Nursing Assistant announcement, before Friday 4 December 2026. Applicants select the shifts and duty locations they wish to be considered for, and are only considered for the shifts and locations they select. Note that the two page resume requirement does not apply to this position. The announcement will be used to fill vacancies as they become available over the next 90 days.</p><h2>What the notice does not say</h2><p>The announcement does not state how many Nursing Assistant posts are open, and it says there may not be current vacancies at all locations when a candidate applies. It does not state a dollar salary figure, which shifts have current openings, or an interview date. The closing date was amended once already, from 4 November to 4 December 2026, so applicants should check the live USAJobs posting for the current date.</p><p><strong>Never pay anyone to apply for this job.</strong> USAJobs applications are free, and the Department of Veterans Affairs will never ask for money in exchange for an application, an assessment or a job offer.</p><p>Sources: <a href="https://www.usajobs.gov/job/888054600">USAJobs</a>, the official vacancy announcement (grade, closing date as amended, qualifications and duties); <a href="https://www.va.gov/ohrm/QualificationStandards/">US Department of Veterans Affairs</a>, the qualification standard referenced in the announcement.</p><h2>Frequently asked questions</h2><h3>What grade is the post?</h3><p>GS-5, the full performance level for this Nursing Assistant vacancy.</p><h3>When do applications close?</h3><p>Applications close on Friday 4 December 2026, amended from 4 November 2026.</p><h3>Who can apply?</h3><p>US citizens. The basic requirement is six months of general experience or one year of education above high school with Nursing Assistant related courses.</p><h3>How many posts are open?</h3><p>The announcement does not state a number. It fills vacancies as they become available over the next 90 days, and there may not be a current vacancy at every location.</p>$$,
$$<p>मियामीमा रहेको ब्रुस W. कार्टर भेटेरन्स मामिला विभाग चिकित्सा केन्द्रले VA नर्सिङ सहायक जागिरका लागि आफ्नो सेवा लाइन र विभागमा नर्सिङ सहायक पदका लागि आवेदन खुलाएको छ। आवेदन शुक्रबार ४ डिसेम्बर २०२६ मा बन्द हुन्छ, अन्तिम मिति ४ नोभेम्बर २०२६ बाट संशोधन भएपछि।</p><table><tbody><tr><td>संस्था</td><td>ब्रुस W. कार्टर भेटेरन्स मामिला विभाग चिकित्सा केन्द्र, मियामी VA स्वास्थ्य सेवा प्रणाली</td></tr><tr><td>पद</td><td>नर्सिङ सहायक, पूर्ण कार्यसम्पादन तह GS-5, विभिन्न सिफ्ट</td></tr><tr><td>तलब</td><td>GS-5 ग्रेड; विज्ञापनले डलर तलब अङ्क बताएको छैन</td></tr><tr><td>आवेदन मिति</td><td>शुक्रबार ४ डिसेम्बर २०२६ मा बन्द, ४ नोभेम्बर २०२६ बाट संशोधित; अर्को ९० दिनमा छनोट</td></tr><tr><td>आवेदन तरिका</td><td>USAJobs बाट अनलाइन</td></tr><tr><td>योग्यता</td><td>छ महिनाको सामान्य अनुभव, वा NA सम्बन्धी पाठ्यक्रमसहित उच्च माध्यमिकभन्दा माथिको एक वर्षको शिक्षा</td></tr><tr><td>छनोट</td><td>VA योग्यता मापदण्डअनुसार आवेदन समीक्षा, त्यसपछि अन्तर्वार्ता</td></tr></tbody></table><h2>पद के हो</h2><p>मियामी VA का नर्सिङ सहायकहरूले नर्सिङ हेरचाह टोलीका सदस्यका रूपमा काम गर्छन्, सुरक्षा चिन्ता पहिचान गरी रिपोर्ट गरेर इजाजतप्राप्त नर्सिङ कर्मचारीलाई सहयोग गर्छन् र तीव्रदेखि दीर्घकालीन अवस्थाका भेटेरन्सलाई प्रत्यक्ष हेरचाह दिन्छन्। काम बाह्य रोगी, भर्ना भएका, घर तथा सामुदायिक जीवन हेरचाह, र तीव्र तथा उप-तीव्र सेटिङमा फैलिएको छ। सिफ्ट फरक हुन्छ र दिन, दिउँसो र साँझको समय, सप्ताहन्त, रात र केही बिदा समावेश हुन सक्छ।</p><h2>कसले आवेदन दिन सक्छ</h2><p>आवेदक अमेरिकी नागरिक हुनुपर्छ; VA नीतिअनुसार योग्य नागरिक भर्ती गर्न नसकिने अवस्थामा मात्र गैर-नागरिक नियुक्त गर्न सकिन्छ। आधारभूत आवश्यकता नर्सिङ सहायकको ज्ञान र सीप प्राप्त गर्ने क्षमता देखाउने छ महिनाको सामान्य अनुभव, वा पेशासँग सम्बन्धित पाठ्यक्रमसहित उच्च माध्यमिकभन्दा माथिको एक वर्षको शिक्षा हो। GS-5 पूर्ण कार्यसम्पादन तहका लागि GS-4 तहमा एक वर्षको क्रमशः जिम्मेवार अनुभव, वा स्वास्थ्य हेरचाह पाठ्यक्रममा २४ सेमेस्टर घण्टासहित स्नातक डिग्री चाहिन्छ। आवेदक लिखित र बोलिने अंग्रेजीमा दक्ष हुनुपर्छ, रोजगारीपूर्व शारीरिक मूल्याङ्कन, पृष्ठभूमि तथा सुरक्षा अनुसन्धान र लागुऔषध परीक्षण पास गर्नुपर्छ।</p><h2>तलब कति छ</h2><p>तलब GS-5 ग्रेडमा निर्धारण हुन्छ, यो रिक्तिका लागि पूर्ण कार्यसम्पादन तह। मैले पढेको विज्ञापन पाठले डलर तलब अङ्क बताएको छैन, त्यसैले ठ्याक्कै तलब प्रस्ताव गरिएको GS-5 चरण र मियामी स्थान दरमा निर्भर गर्छ।</p><h2>कसरी आवेदन दिने</h2><p>शुक्रबार ४ डिसेम्बर २०२६ अघि USAJobs बाट अनलाइन आवेदन दिनुहोस्, मियामी VA नर्सिङ सहायक विज्ञापनमा। आवेदकले आफूले विचार गर्न चाहेको सिफ्ट र कर्तव्य स्थान छनोट गर्छन्, र छनोट गरिएका सिफ्ट र स्थानका लागि मात्र विचार गरिन्छ। यो पदका लागि दुई पृष्ठको रिजुम आवश्यकता लागू हुँदैन।</p><h2>सूचनाले के भनेको छैन</h2><p>विज्ञापनले कति नर्सिङ सहायक पद खुलेका छन् भन्ने बताएको छैन, र उम्मेदवारले आवेदन दिँदा सबै स्थानमा हाल रिक्ति नहुन सक्छ भन्ने उल्लेख गर्छ। डलर तलब अङ्क, कुन सिफ्टमा हाल रिक्ति छ, वा अन्तर्वार्ता मिति पनि बताएको छैन। अन्तिम मिति एक पटक संशोधन भइसकेको छ, ४ नोभेम्बरबाट ४ डिसेम्बर २०२६ मा।</p><p><strong>यो जागिरका लागि कसैलाई पनि पैसा नतिर्नुहोस्।</strong> USAJobs मा आवेदन निःशुल्क छ, र भेटेरन्स मामिला विभागले आवेदन, मूल्याङ्कन वा जागिर प्रस्तावका लागि कहिल्यै पैसा माग्दैन।</p><p>स्रोतहरू: <a href="https://www.usajobs.gov/job/888054600">USAJobs</a>, आधिकारिक रिक्ति विज्ञापन; <a href="https://www.va.gov/ohrm/QualificationStandards/">अमेरिकी भेटेरन्स मामिला विभाग</a>, विज्ञापनमा सन्दर्भ गरिएको योग्यता मापदण्ड।</p><h2>बारम्बार सोधिने प्रश्नहरू</h2><h3>पद कुन ग्रेडको हो?</h3><p>GS-5, यो नर्सिङ सहायक रिक्तिका लागि पूर्ण कार्यसम्पादन तह।</p><h3>आवेदन कहिले बन्द हुन्छ?</h3><p>आवेदन शुक्रबार ४ डिसेम्बर २०२६ मा बन्द हुन्छ, ४ नोभेम्बर २०२६ बाट संशोधित।</p><h3>कसले आवेदन दिन सक्छ?</h3><p>अमेरिकी नागरिक। आधारभूत आवश्यकता छ महिनाको सामान्य अनुभव वा नर्सिङ सहायक सम्बन्धी पाठ्यक्रमसहित उच्च माध्यमिकभन्दा माथिको एक वर्षको शिक्षा हो।</p>$$,
